const readOne = operation({
    label: "readOne",
    input: parseIssueId,
    run: (_deps, ctx) => booted.detail(ctx.input),
  })

const saveIssue = operation({
    label: "saveIssue",
    input: parseCreateInput,
    run: (_deps, ctx) => save.create(ctx.input),
  })

export const editIssue = operation({
  label: "editIssue",
  input: parseEditInput,
  depends: { tx: store.tx },
  run: async ({ tx }, ctx) => {
    const saved = await loadSaved(tx, ctx.input.id);
    checkFresh(saved, ctx.input.baseRevision);
    const updated = applyEdit(saved, ctx.input, ctx.clock.currentTimeMillis());
    await writeIssue(tx, updated);
    const names = editNames(ctx.input);
    await recordActivity(
      tx,
      updated.id,
      "edited",
      names.length > 0 ? `edited ${names.join(", ")}` : "edited",
      updated.updatedAt,
    );
    return updated;
  },
})

export const listRemote = operation({
  label: "list",
  meta: [tool({ description: "list the saved issues", schema: {} })],
  depends: { issues: getIssues },
  run: async ({ issues }) => {
    try {
      return await issues.run();
    } catch (error: unknown) {
      throw await readRemoteError(error, "issues");
    }
  },
})

const readCapability = operation({
    label: "readCapability",
    run: () => ({ enabled: booted.draft.enabled }),
  })

export const readCapability = operation({
  label: "readCapability",
  depends: { draft: draftHelper },
  run: ({ draft }) => ({ enabled: draft.enabled }),
})

function createSerial(scope: Scope.Handle): {
  save: Booted.Save;
  detail: (id: string) => Promise<Issues.Detail>;
}

export function stream(c: Context, write: Stream.Write): Response {
  const session = (c as Context<SessionEnv>).get("tinker.session");
  if (!session) raise("NoSession", { label: "stream" });
  (c as Context<SessionEnv>).set("tinker.kept", true);
  const encoder = new TextEncoder();
  const label = `${c.req.method} ${c.req.routePath} body`;
  let closed = false;
  const closeOnce = (graceful: boolean): void => {
    if (closed) return;
    closed = true;
    ignoreRejection(session.close(graceful ? { graceful: true } : undefined));
  };
  const readable = new ReadableStream<Uint8Array>({
    start(controller) {
      const emit: Stream.Emit = (chunk) => {
        controller.enqueue(typeof chunk === "string" ? encoder.encode(chunk) : chunk);
      };
      const running = session.run({
        label,
        run: (_deps, ctx) => write(emit, ctx),
      });
      const settled = Promise.resolve(running);
      ignoreRejection(
        settled.then(
          () => {
            controller.close();
          },
          (error: unknown) => {
            controller.error(error);
          },
        ),
      );
      const finish = settled.then(
        () => closeOnce(true),
        () => closeOnce(true),
      );
      ignoreRejection(finish);
    },
    cancel() {
      closeOnce(false);
    },
  });
  if (c.res.headers.get("content-type") === null)
    c.header("Content-Type", "text/plain; charset=UTF-8");
  return c.body(readable);
}

export const startDraft = operation({
  label: "startDraft",
  input: parseDraftInput,
  depends: {
    draft: draftHelper,
    detail: readDetail,
    turn: draftTurn,
    text: triage.text.controller,
    status: triage.status.controller,
  },
  run: async ({ draft, detail, turn, text, status }, ctx) => {
    if (draft.enabled === false) raise("DraftOff", {});
    await detail.run({ input: ctx.input.id });
    const input = ctx.input;
    return {
      stream: async (emit: Stream.Emit, signal: AbortSignal): Promise<void> => {
        let live = "";
        const unText = text.watch((next) => {
          if (next.length > live.length) {
            emit(draftFrame({ kind: "text", text: next.slice(live.length) }));
            live = next;
          }
        });
        const unStatus = status.watch((next) => {
          if (next === "running") emit(draftFrame({ kind: "status", status: next }));
        });
        try {
          const draftText = await turn.run({ input });
          try {
            emit(draftFrame({ kind: "status", status: "done" }));
            emit(draftFrame({ kind: "done", draft: draftText }));
            emit(draftFrame({ kind: "terminal", status: "done", draft: draftText }));
          } catch {
            return;
          }
        } catch {
          const outcome: Draft.Outcome = signal.aborted ? "cancelled" : "failed";
          try {
            emit(draftFrame({ kind: "status", status: outcome }));
            emit(draftFrame({ kind: "terminal", status: outcome, draft: "" }));
          } catch {
            return;
          }
        } finally {
          unText();
          unStatus();
        }
      },
    };
  },
})

function serveRequests(scope: Scope.Handle, wiring: HonoScope.Wiring): Middleware {
  return createMiddleware<SessionEnv>(async (c, next) => {
    const raw = c.req.raw;
    const session = scope.createSession({
      tags: [request(raw), ...(wiring.tags?.(c) ?? [])],
    });
    c.set("tinker.session", session);
    c.set("tinker.onError", wiring.onError);
    const onAbort = (): void => {
      ignoreRejection(session.close());
    };
    raw.signal.addEventListener("abort", onAbort, { once: true });
    try {
      await next();
    } finally {
      if (!(c as Context<SessionEnv>).get("tinker.kept")) {
        raw.signal.removeEventListener("abort", onAbort);
        await session.close({ graceful: true });
      }
    }
  });
}

