export function memoryPair(): readonly [Sync.Transport, Sync.Transport] {
  const leftMessages = new Set<(message: Sync.Message) => void>();
  const rightMessages = new Set<(message: Sync.Message) => void>();
  const leftCloses = new Set<() => void>();
  const rightCloses = new Set<() => void>();
  let closed = false;
  function sendLeft(message: Sync.Message): void {
    if (closed) return;
    deliver(rightMessages, message);
  }
  function sendRight(message: Sync.Message): void {
    if (closed) return;
    deliver(leftMessages, message);
  }
  function close(): void {
    if (closed) return;
    closed = true;
    for (const listener of leftCloses) listener();
    for (const listener of rightCloses) listener();
  }
  const left: Sync.Transport = {
    send: sendLeft,
    onMessage: (listener) => listen(leftMessages, listener),
    onClose: (listener) => listen(leftCloses, listener),
    close,
  };
  const right: Sync.Transport = {
    send: sendRight,
    onMessage: (listener) => listen(rightMessages, listener),
    onClose: (listener) => listen(rightCloses, listener),
    close,
  };
  return [left, right];
}

function mapCodexEvent(event: ThreadEvent, hooks: Harness.Hooks, fold: Fold): boolean {
  hooks.emit(event);
  if (event.type === "thread.started") {
    hooks.id(event.thread_id);
    return false;
  }
  if (
    event.type === "item.started" ||
    event.type === "item.updated" ||
    event.type === "item.completed"
  ) {
    readThreadItem(event, hooks, fold);
    return false;
  }
  if (event.type === "turn.completed") {
    hooks.usage({
      input: event.usage.input_tokens,
      cached: event.usage.cached_input_tokens,
      output: event.usage.output_tokens,
    });
    fold.usage = event.usage;
    return true;
  }
  if (event.type === "turn.failed") {
    fold.failure = event.error;
    return true;
  }
  return false;
}

export function reconnectingTransport(baseUrl: string): ReconnectingWire {
  const id = Math.random().toString(36).slice(2);
  const url = `${baseUrl}/sync?client=${id}`;
  let status: WireStatus = "connecting";
  const watchers = new Set<(status: WireStatus) => void>();
  const arrivals = new Set<(message: Sync.Message) => void>();
  const partings = new Set<() => void>();
  const flight = new AbortController();
  let stream: EventSource | null = null;
  let lastRegister: Sync.Message | null = null;
  let queue: Promise<void> = Promise.resolve();
  let settled = false;
  let closed = false;
  let gated: Promise<void> = Promise.resolve();

  function flip(next: WireStatus): void {
    status = next;
    for (const watcher of Array.from(watchers)) watcher(next);
  }

  function fireClose(): void {
    for (const parting of Array.from(partings)) parting();
  }

  /** A stream error before the first open fails the boot: `subscribe` rejects `ready` and the
   * dead page renders. Any later error only flips the status; `subscribe` stays attached. */
  function drop(): void {
    if (closed) return;
    if (settled === false) {
      settled = true;
      flip("failed");
      fireClose();
      return;
    }
    flip("dropped");
  }

  /** Open one stream: `opened` resolves on open and rejects on the first error. Later errors
   * ride the live `onerror` handler, so one rejected `opened` means exactly one drop. */
  function open(): { readonly stream: EventSource; readonly opened: Promise<void> } {
    const next = new EventSource(url);
    stream = next;
    let failOpen: (error: unknown) => void = () => undefined;
    const opened = new Promise<void>((resolve, reject) => {
      failOpen = reject;
      next.onopen = () => resolve();
    });
    opened.then(
      () => {
        if (closed || stream !== next) return;
        settled = true;
        flip("live");
      },
      () => {
        if (closed || stream !== next) return;
        stream = null;
        next.close();
        drop();
      },
    );
    next.onerror = () => {
      if (closed || stream !== next) return;
      if (settled === false) failOpen(fail("SyncDropped", { reason: "stream failed" }));
      else drop();
    };
    next.onmessage = (event) => {
      if (closed || stream !== next) return;
      let message: Sync.Message;
      try {
        message = readData(event);
      } catch {
        drop();
        return;
      }
      for (const arrival of Array.from(arrivals)) arrival(message);
    };
    return { stream: next, opened };
  }

  gated = open().opened;
  gated.then(undefined, () => undefined);

  const post = async (message: Sync.Message, signal: AbortSignal): Promise<void> => {
    const received = await tryPost(message, signal);
    if (received !== undefined && received.ok === false) drop();
  };

  /** POST one message; undefined when the wire closed first or the send itself failed. */
  const tryPost = async (
    message: Sync.Message,
    signal: AbortSignal,
  ): Promise<Response | undefined> => {
    if (closed || signal.aborted) return undefined;
    try {
      return await fetch(url, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify(message),
        signal,
      });
    } catch {
      if (closed === false && signal.aborted === false) drop();
      return undefined;
    }
  };

  /** POST one queued message behind its stream's open; a refused POST drops the wire. */
  const sendQueued = (message: Sync.Message): void => {
    if (message.type === "register") lastRegister = message;
    const gate = gated;
    queue = queue.then(() => gate.then(() => post(message, flight.signal)));
  };

  return {
    send: (message) => {
      if (closed) return;
      sendQueued(message);
    },
    onMessage: (listener) => {
      arrivals.add(listener);
      return () => {
        arrivals.delete(listener);
      };
    },
    onClose: (listener) => {
      partings.add(listener);
      return () => {
        partings.delete(listener);
      };
    },
    close: () => {
      if (closed) return;
      closed = true;
      flight.abort();
      stream?.close();
      stream = null;
      fireClose();
    },
    status: () => status,
    onStatus: (listener) => {
      watchers.add(listener);
      return () => {
        watchers.delete(listener);
      };
    },
    reconnect: async () => {
      if (closed) return;
      flip("connecting");
      stream?.close();
      stream = null;
      const { opened } = open();
      gated = opened;
      try {
        await opened;
      } catch {
        drop();
        return;
      }
      if (closed) return;
      const replay = lastRegister;
      if (replay !== null) queue = queue.then(() => post(replay, flight.signal));
    },
  };
}

