export const startDraft = operation({
  label: "startDraft",
  input: parseDraftInput,
  depends: {
    draft: draftHelper,
    detail: readDetail,
    turn: draftTurn,
    text: triage.text.controller,
    status: triage.status.controller,
  },
  run: async ({ draft, detail, turn, text, status }, ctx) => {
    if (draft.enabled === false) raise("DraftOff", {});
    await detail.run({ input: ctx.input.id });
    const input = ctx.input;
    return {
      stream: async (emit: Stream.Emit, signal: AbortSignal): Promise<void> => {
        let live = "";
        const unText = text.watch((next) => {
          if (next.length > live.length) {
            emit(draftFrame({ kind: "text", text: next.slice(live.length) }));
            live = next;
          }
        });
        const unStatus = status.watch((next) => {
          if (next === "running") emit(draftFrame({ kind: "status", status: next }));
        });
        try {
          const draftText = await turn.run({ input });
          try {
            emit(draftFrame({ kind: "status", status: "done" }));
            emit(draftFrame({ kind: "done", draft: draftText }));
            emit(draftFrame({ kind: "terminal", status: "done", draft: draftText }));
          } catch {
            return;
          }
        } catch {
          const outcome: Draft.Outcome = signal.aborted ? "cancelled" : "failed";
          try {
            emit(draftFrame({ kind: "status", status: outcome }));
            emit(draftFrame({ kind: "terminal", status: outcome, draft: "" }));
          } catch {
            return;
          }
        } finally {
          unText();
          unStatus();
        }
      },
    };
  },
})

drafter = resource({
  label: "drafter",
  depends: { open: openDraft, run: draftRun.controller, selected: selectedId.controller },
  factory: ({ open, run, selected }, { defer }): Drafter => {
    let epoch = 0;
    let reader: ReadableStreamDefaultReader<Uint8Array> | null = null;
    const stopSelection = selected.watch(() => {
      stop();
      run.set(quietRun);
    });
    defer(stopSelection);
    defer(() => stop());
    function stop(): void {
      epoch += 1;
      reader?.cancel().then(undefined, () => undefined);
      reader = null;
    }
    async function pump(stream: ReadableStream<Uint8Array>, mine: number): Promise<void> {
      if (mine !== epoch) {
        await stream.cancel().then(undefined, () => undefined);
        return;
      }
      const owned = stream.getReader();
      reader = owned;
      try {
        landFinished(mine, await readOutcome(owned, mine));
      } catch (error: unknown) {
        landThrown(mine, owned, error);
      } finally {
        owned.releaseLock();
        if (reader === owned) reader = null;
      }
    }
    async function readOutcome(
      owned: ReadableStreamDefaultReader<Uint8Array>,
      mine: number,
    ): Promise<Draft.Outcome> {
      const decoder = new TextDecoder();
      const pumpState = {
        tail: "",
        apply: (event: Draft.Event) => {
          if (mine === epoch) applyDraft(run, event);
        },
      };
      let outcome: Draft.Outcome = "failed";
      for (;;) {
        const next = await owned.read();
        if (next.done) break;
        const finished = pumpLines(pumpState, decoder.decode(next.value, { stream: true }));
        if (finished !== undefined) outcome = finished;
      }
      const closing = readLine(pumpState.tail);
      if (closing !== null && closing.kind === "terminal") return closing.status;
      return outcome;
    }
    function landThrown(
      mine: number,
      owned: ReadableStreamDefaultReader<Uint8Array> | null,
      error: unknown,
    ): void {
      if (mine !== epoch) return;
      if (isStaleCancel(error)) {
        run.update((prev) => (prev.view === "running" ? { ...prev, view: "cancelled" } : prev));
        return;
      }
      owned?.cancel().then(undefined, () => undefined);
      run.set(readFailedRun(error));
    }
    function landFinished(mine: number, outcome: Draft.Outcome): void {
      if (mine !== epoch) return;
      if (outcome === "failed") {
        run.update((prev) => ({
          ...prev,
          view: "failed",
          notice: prev.notice ?? HELPER_FAILED,
        }));
        return;
      }
      run.update((prev) => ({ ...prev, view: readView(outcome) }));
    }
    return {
      start(id: string, prompt: string): Promise<void> {
        stop();
        const mine = epoch;
        run.set({ view: "running", text: "", draft: "", notice: null });
        return open.run({ input: { id, prompt } }).then(
          (stream) => pump(stream, mine),
          (error: unknown) => landThrown(mine, null, error),
        );
      },
      cancel(): void {
        stop();
        run.update((prev) => (prev.view === "running" ? { ...prev, view: "cancelled" } : prev));
      },
      discard(): void {
        stop();
        run.set(quietRun);
      },
    };
  },
})

