export async function connectTab(baseUrl: string): Promise<TabSync.Connected> {
  const id = Math.random().toString(36).slice(2);
  const stream = new EventSource(`${baseUrl}/sync?client=${id}`);
  try {
    await opened(stream);
  } catch (error) {
    stream.close();
    throw error;
  }
  const dropped = new Set<() => void>();
  const flight = new AbortController();
  let closed = false;
  let tail: Promise<void> = Promise.resolve();
  const fire = (): void => {
    for (const listener of Array.from(dropped)) listener();
  };
  const closeOnce = (): void => {
    if (closed) return;
    closed = true;
    flight.abort();
    stream.close();
    fire();
  };
  stream.onerror = () => closeOnce();
  const post = async (message: Sync.Message, signal: AbortSignal): Promise<void> => {
    let res: Response;
    try {
      res = await fetch(`${baseUrl}/sync?client=${id}`, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify(message),
        signal,
      });
    } catch {
      closeOnce();
      return;
    }
    if (!res.ok) closeOnce();
  };
  const transport: Sync.Transport = {
    send: (message) => {
      if (closed) return;
      tail = tail.then(() => post(message, flight.signal));
    },
    onMessage: (listener) => {
      stream.onmessage = (event) => {
        try {
          listener(readData(event));
        } catch (error) {
          if (isError(error, "SyncDropped")) closeOnce();
          else throw error;
        }
      };
      return () => {
        stream.onmessage = null;
      };
    },
    onClose: (listener) => {
      dropped.add(listener);
      return () => {
        dropped.delete(listener);
      };
    },
    close: () => closeOnce(),
  };
  const scope = createScope({
    tags: [sync(issueList), api.config({ baseUrl })],
    extensions: [subscribe(transport)],
  });
  async function closeConnection(): Promise<Scope.Result> {
    closeOnce();
    await tail;
    return scope.close();
  }
  try {
    await scope.ready;
  } catch (error) {
    const cleaned = await closeConnection();
    if (cleaned.status === "failed" || (cleaned.teardownErrors ?? []).length > 0) {
      const cleanup = fail("SyncDropped", { reason: "cleanup failed" });
      cleanup.cause = error;
      throw cleanup;
    }
    throw error;
  }
  return {
    scope,
    close: closeConnection,
    onDrop: (listener) => {
      if (closed) {
        listener();
        return () => undefined;
      }
      dropped.add(listener);
      return () => {
        dropped.delete(listener);
      };
    },
  };
}

