export async function tour(): Promise<readonly Process.Result[]> {
  const stop = new AbortController();
  setTimeout(() => stop.abort(), 30);
  return [
    await run(shell, ["help"]),
    await run(shell, ["check", "a.yaml"]),
    await run(shell, ["count", "3"]),
    await run(shell, ["serve"], undefined, stop.signal),
  ];
}

export async function tour(): Promise<string> {
  const loads = { count: 0 };
  const shell: Process.Shell = {
    name: "tour",
    version: "0.0.0",
    commands: [
      { name: "double", description: "double a number", entry: () => ({ op: doubleCommand }) },
      lazyPingRoute(loads),
    ],
  };
  const helped = await run(shell, ["help"]);
  const answered = await run(shell, ["double", "21"]);
  const pinged = await run(shell, ["ping"]);
  return `${helped.code} ${answered.code} ${answered.stdout} ${loads.count} ${pinged.code}`;
}

export async function execute(
  entry: Process.Entry,
  rest: readonly string[],
  out: Process.Io,
  opts?: { readonly signal?: AbortSignal; readonly usage?: string },
): Promise<number> {
  const signal = opts?.signal;
  /** Read through a call, never a narrowed constant: the signal may abort mid-run. */
  const cancelled = (): boolean => signal?.aborted === true;
  if (cancelled()) return 130;
  const scope = rootFor(entry, rest, out);
  const stop = (): void => void scope.close();
  signal?.addEventListener("abort", stop, { once: true });
  try {
    await scope.ready;
    return await scope.run(entry.op);
  } catch (error: unknown) {
    return readFailure(error, out, cancelled(), opts?.usage);
  } finally {
    signal?.removeEventListener("abort", stop);
    await scope.close({ graceful: !cancelled() });
  }
}

