export async function main(shell: Process.Shell, args?: readonly string[]): Promise<never> {
  const proc = readProc();
  if (proc === undefined)
    raise("NoProcess", { reason: "main needs a process to read argv and exit" });
  const controller = new AbortController();
  const abort = (): void => controller.abort();
  proc.on("SIGINT", abort);
  proc.on("SIGTERM", abort);
  const result = await run(
    shell,
    args ?? proc.argv.slice(2),
    { write: (s) => void proc.stdout.write(s), error: (s) => void proc.stderr.write(s) },
    controller.signal,
  );
  return proc.exit(result.code);
}

export async function run(
  shell: Process.Shell,
  args: readonly string[],
  given?: Partial<Process.Io>,
  signal?: AbortSignal,
): Promise<Process.Result> {
  let stdout = "";
  let stderr = "";
  const out: Process.Io = {
    write: (s) => {
      stdout += s;
      given?.write?.(s);
    },
    error: (s) => {
      stderr += s;
      given?.error?.(s);
    },
  };
  const done = (code: number): Process.Result => ({ code, stdout, stderr });
  const usage = usageOf(shell);
  const [name, ...rest] = args;
  if (name === undefined || name === "help" || name === "--help") {
    out.write(usage);
    return done(0);
  }
  if (name === "--version") {
    out.write(`${shell.version}\n`);
    return done(0);
  }
  const route = shell.commands.find((row) => row.name === name);
  if (route === undefined) {
    out.error(usage);
    return done(2);
  }
  let entry: Process.Entry;
  try {
    entry = await route.entry(rest);
  } catch (error: unknown) {
    out.error(printError(error));
    return done(1);
  }
  return done(await execute(entry, rest, out, { signal, usage }));
}

async function askGateway(
  model: EvaluationModel,
  state: Blueprint.NodeState | Blueprint.PairState | Blueprint.WordsState,
  questions: Readonly<Record<string, Blueprint.Question>>,
  signal: AbortSignal,
): Promise<Readonly<Record<string, Blueprint.Answer>>> {
  for (let attempt = 0; attempt < 5; attempt++) {
    try {
      const { answers } = await evaluate({ model, state, questions, abortSignal: signal });
      return answers;
    } catch (error: unknown) {
      if (!RATE_LIMITED.test(messageOf(error))) throw error;
      await wait(8000 * (attempt + 1), signal);
    }
  }
  raise("JevUnavailable", {}, "blueprint: gave up after rate-limit retries");
}

