function renderDead(element: ReturnType<typeof createRoot>, phase: DeadPhase): void {
  element.render(
    <StrictMode>
      <main>
        <h1>Issues</h1>
        <p role="alert">Could not connect. Your drafts are kept in this tab.</p>
        {phase === "retrying" ? (
          <button type="button" disabled>
            Reconnect
          </button>
        ) : (
          <button type="button" onClick={() => retry(element)}>
            Reconnect
          </button>
        )}
        {phase === "retrying" ? <p aria-live="polite">Reconnecting…</p> : null}
        {phase === "failed" ? <p role="alert">Still no connection. Try again.</p> : null}
      </main>
    </StrictMode>,
  );
  if (phase === "retrying") {
    const retried = start(element);
    retried.then(
      (recovered) => {
        if (recovered !== true) renderDead(element, "failed");
      },
      () => renderDead(element, "failed"),
    );
  }
}

function servePort(
  host: string,
  port: number,
  observe: Observe.Config | undefined,
): HonoScope.Serve {
  return (app) =>
    new Promise<{ readonly close: () => void }>((resolve, reject) => {
      void serveClient(app).then(() => {
        app.onError(reportUnmapped(observe));
        const server = serve({ fetch: app.fetch, hostname: host, port }, (info) => {
          writeLog("listening", { host, port: info.port });
          resolve({ close: () => void server.close() });
        });
        server.once("error", reject);
      }, reject);
    });
}

