export function stream(
  c: Context,
  op: Operation.Handle<unknown, unknown>,
  call?: Scope.Invocation<unknown>,
): Response {
  const session = (c as Context<SessionEnv>).get("tinker.session");
  if (!session) raise("NoSession", { label: "stream" });
  (c as Context<SessionEnv>).set("tinker.kept", true);
  const encoder = new TextEncoder();
  let closed = false;
  const closeOnce = (graceful: boolean): void => {
    if (closed) return;
    closed = true;
    ignoreRejection(session.close(graceful ? { graceful: true } : undefined));
  };
  const readable = new ReadableStream<Uint8Array>({
    start(controller) {
      const write: Stream.Emit = (chunk) => {
        controller.enqueue(typeof chunk === "string" ? encoder.encode(chunk) : chunk);
      };
      // Bind the writer on a child session for this response, but run the
      // body without a tagged call: a caught failure in one of its subflows
      // must not turn a successful terminal frame into a rejected body.
      const body = session.createSession({
        tags: [call?.tags, emit(write)],
        ...(call?.ns === undefined ? {} : { ns: call.ns }),
      });
      const running = body.run(op, {
        input: call?.input,
        rawInput: call?.rawInput,
      } as Scope.ProvideInput<unknown>);
      const settled = Promise.resolve(running);
      const finish = settled.then(
        async () => {
          controller.close();
          await body.close({ graceful: true });
          closeOnce(true);
        },
        async (error: unknown) => {
          await body.close({ graceful: true });
          // Record an uncaught body error on the request too: its defers
          // must see `failed` even though the bound child has closed.
          try {
            await session.run({
              label: "stream failure",
              run: async () => {
                throw error;
              },
            });
          } catch {
            // The reader receives the original error below.
          }
          controller.error(error);
          closeOnce(true);
        },
      );
      ignoreRejection(finish);
    },
    cancel() {
      closeOnce(false);
    },
  });
  if (c.res.headers.get("content-type") === null)
    c.header("Content-Type", "text/plain; charset=UTF-8");
  return c.body(readable);
}

export function stream(
  c: Context,
  op: Operation.Handle<unknown, unknown>,
  call?: Scope.Invocation<unknown>,
): Response {
  const session = (c as Context<SessionEnv>).get("tinker.session");
  if (!session) raise("NoSession", { label: "stream" });
  (c as Context<SessionEnv>).set("tinker.kept", true);
  const encoder = new TextEncoder();
  let closed = false;
  const closeOnce = (graceful: boolean): void => {
    if (closed) return;
    closed = true;
    ignoreRejection(session.close(graceful ? { graceful: true } : undefined));
  };
  const readable = new ReadableStream<Uint8Array>({
    start(controller) {
      const write: Stream.Emit = (chunk) => {
        controller.enqueue(typeof chunk === "string" ? encoder.encode(chunk) : chunk);
      };
      // Bind the writer on a child session for this response, but run the
      // body without a tagged call: a caught failure in one of its subflows
      // must not turn a successful terminal frame into a rejected body.
      const body = session.createSession({
        tags: [call?.tags, emit(write)],
        ...(call?.ns === undefined ? {} : { ns: call.ns }),
      });
      const running = body.run(op, {
        input: call?.input,
        rawInput: call?.rawInput,
      } as Scope.ProvideInput<unknown>);
      const settled = Promise.resolve(running);
      const finish = settled.then(
        () => {
          controller.close();
          closeOnce(true);
        },
        (error: unknown) => {
          controller.error(error);
          closeOnce(true);
        },
      );
      ignoreRejection(finish);
    },
    cancel() {
      closeOnce(false);
    },
  });
  if (c.res.headers.get("content-type") === null)
    c.header("Content-Type", "text/plain; charset=UTF-8");
  return c.body(readable);
}

export function askCommand(
  frame: Pick<Tinkerer.Frame, "turn" | "text">,
  opts?: {
    readonly name?: string;
    readonly description?: string;
    readonly options?: Scope.Options;
  },
): Process.Route {
  const name = opts?.name ?? "ask";
  const op = operation({
    label: name,
    depends: {
      argv: argv.required,
      io: io.required,
      text: frame.text.controller,
      turn: frame.turn,
    },
    run: async ({ argv: args, io: out, text, turn }) => {
      const prompt = readPrompt(args);
      if (prompt === "") {
        out.error(`usage: ${name} <prompt>\n`);
        return 2;
      }
      const stop = text.watch((next, previous) => out.write(next.slice(previous.length)));
      try {
        const reply = await turn.run({ input: prompt });
        out.write("\n");
        return reply.finish === "stop" ? 0 : 3;
      } finally {
        stop();
      }
    },
  });
  return {
    name,
    description: opts?.description ?? "run one turn and print the answer as it streams",
    entry: () => ({ op, options: opts?.options }),
  };
}

export function stream(c: Context, write: Stream.Write): Response {
  const session = (c as Context<SessionEnv>).get("tinker.session");
  if (!session) raise("NoSession", { label: "stream" });
  (c as Context<SessionEnv>).set("tinker.kept", true);
  const encoder = new TextEncoder();
  const label = `${c.req.method} ${c.req.routePath} body`;
  let closed = false;
  const closeOnce = (graceful: boolean): void => {
    if (closed) return;
    closed = true;
    ignoreRejection(session.close(graceful ? { graceful: true } : undefined));
  };
  const readable = new ReadableStream<Uint8Array>({
    start(controller) {
      const emit: Stream.Emit = (chunk) => {
        controller.enqueue(typeof chunk === "string" ? encoder.encode(chunk) : chunk);
      };
      const running = session.run({
        label,
        run: (_deps, ctx) => write(emit, ctx),
      });
      const settled = Promise.resolve(running);
      ignoreRejection(
        settled.then(
          () => {
            controller.close();
          },
          (error: unknown) => {
            controller.error(error);
          },
        ),
      );
      const finish = settled.then(
        () => closeOnce(true),
        () => closeOnce(true),
      );
      ignoreRejection(finish);
    },
    cancel() {
      closeOnce(false);
    },
  });
  if (c.res.headers.get("content-type") === null)
    c.header("Content-Type", "text/plain; charset=UTF-8");
  return c.body(readable);
}

function operation(
    endpoint: HttpClient.Endpoint<unknown, unknown>,
  ): Operation.Handle<Promise<unknown>, unknown> {
    const read = endpoint.response;
    return operationCore({
      label: `${frame.label}.${endpoint.label}`,
      input: endpoint.input,
      depends: { client: frame.client, config: frame.config.all },
      run: async ({ client, config }, ctx) => {
        const request = applyConfig(endpoint.request(ctx.input), mergeConfig(config));
        const received = await client.execute(request, ctx);
        if (read !== undefined) return read(received);
        return received;
      },
    });
  }

function turn(
    shape: Harness.TurnShape<unknown, T, R, unknown>,
  ): Operation.Handle<Promise<unknown>, unknown> {
    const read = shape.response;
    return operation({
      label: `${frame.label}.${shape.label}`,
      input: shape.input,
      depends: { thread: frame.thread, status: status.controller, text: text.controller },
      run: async ({ thread, status, text }, ctx) => {
        if (ctx.signal.aborted) throw ctx.signal.reason;
        const started = ctx.clock.currentTimeMillis();
        status.set("running");
        text.set("");
        const span = ctx.obs.span;
        if (span) span.attributes.adapter = frame.adapter.label;
        try {
          const result = await (await thread).run(shape.request(ctx.input));
          status.set("done");
          const ms = ctx.clock.currentTimeMillis() - started;
          ctx.log("harness turn", { harness: frame.label, turn: shape.label, status: "done", ms });
          if (read !== undefined) return read(result);
          return result;
        } catch (error) {
          if (!ctx.signal.aborted) status.set("failed");
          const ms = ctx.clock.currentTimeMillis() - started;
          ctx.log("harness turn", {
            harness: frame.label,
            turn: shape.label,
            status: ctx.signal.aborted ? "cancelled" : "failed",
            ms,
          });
          throw error;
        }
      },
    });
  }

function readCommand<T, I>(
  name: string,
  target: Operation.Handle<T, I>,
  sugar: Process.Sugar<T>,
): Process.Command {
  return operation({
    label: name,
    depends: { argv: argv.required, io: io.required, op: target },
    run: async ({ argv: args, io: out, op: flow }, ctx) => {
      const started = ctx.clock.currentTimeMillis();
      const value = (await (sugar.input === undefined
        ? (flow as { run(): T }).run()
        : flow.run({ rawInput: sugar.input(args) }))) as Awaited<T>;
      const text = sugar.respond === undefined ? readJsonLine(value) : sugar.respond(value);
      if (text !== undefined) out.write(text);
      ctx.log("command", { command: name, code: 0, ms: ctx.clock.currentTimeMillis() - started });
      return 0;
    },
  });
}

export function expose(op: Operation.Handle<unknown, unknown>, meta: Mcp.Tool): Mcp.Row {
  return { op, meta };
}

export function mcp(wiring: Mcp.Wiring): Scope.Extension<McpServer> {
  return extension<McpServer>({
    label: "mcp",
    start: async (scope, _ctx, next) => {
      await next();
      const server = new McpServer({ name: wiring.name, version: wiring.version });
      for (const row of readMany(wiring.tools)) {
        const name = row.meta.name ?? row.op.label;
        server.registerTool(
          name,
          { description: row.meta.description, inputSchema: row.meta.schema },
          readCall(scope, name, row.op, row.meta),
        );
      }
      return server;
    },
  });
}

export function hono(
  routes: Many<HonoScope.Row>,
  wiring?: HonoScope.Wiring,
): { readonly extension: Scope.Extension<Hono> } {
  return {
    extension: extension<Hono>({
      label: "hono",
      start: async (scope, ctx, next) => {
        await next();
        const mounted = await Promise.all(
          readMany(routes).map(async (row) => ({ row, op: await row.load() })),
        );
        const app = new Hono().use(serveRequests(scope, wiring));
        for (const { row, op } of mounted) app.on(row.method, row.path, answerRoute(op, row.route));
        wiring?.mount?.(app);
        /** Register the stop BEFORE the bind settles, so a close landing mid-bind
         * still drains this defer (and keeps the fast-close path off the table).
         * The defer reads the settled stop out of the box; when the bind lands
         * after the defer already ran, it stops at once — exactly one stop either way. */
        let served: HonoScope.Served | undefined;
        let stopped = false;
        ctx.defer(() => {
          stopped = true;
          return readStop(served);
        });
        served = await wiring?.serve?.(app);
        if (stopped) await readStop(served);
        return app;
      },
    }),
  };
}

export function drizzleStore<Config, DB extends DrizzleStore.Transactional>(config: {
  label?: string;
  target?: "scope" | "namespace";
  open: (config: Config, tools: DrizzleStore.Tools) => DB | PromiseLike<DB>;
  close?: (db: DB) => void | PromiseLike<void>;
  meta?: Tag.Bindings;
}): DrizzleStore.Frame<Config, DB> {
  const openDb = config.open;
  const closeDb = config.close;
  const frameLabel = config.label ?? "drizzle";
  const configTag: Tag.Handle<Config> = tag({ label: `${frameLabel}.config` });
  const db: Resource.Handle<Promise<DB>> = resource({
    label: `${frameLabel}.db`,
    target: config.target ?? "scope",
    depends: { config: configTag },
    meta: config.meta,
    factory: ({ config: bound }, ctx) => {
      const opened = openDb(bound, { logger: readLogger(ctx) });
      return Promise.resolve(opened).then((instance) => {
        if (closeDb) ctx.defer(() => closeDb(instance));
        return instance;
      });
    },
  });
  const tx: Resource.Handle<Promise<DrizzleStore.Tx<DB>>> = resource({
    label: `${frameLabel}.tx`,
    target: "session",
    depends: { db },
    meta: config.meta,
    factory: ({ db: client }, ctx) => {
      const started = readTransaction(client);
      ctx.defer((end) => settleTransaction(started, end));
      return started.handle;
    },
  });
  return { label: frameLabel, config: configTag, db, tx };
}

export function tinkerer(
  config: {
    label?: string;
    tools?: Many<Tinkerer.Tool>;
    gate?: Tinkerer.Gate;
  } = {},
): Tinkerer.Frame {
  const label = config.label ?? "tinkerer";
  const rows = readMany(config.tools);
  checkDuplicateTools(label, rows);
  const configTag = tag<Partial<Tinkerer.Config>>({ label: `${label}.config` });
  const mode = tag<Tinkerer.Mode>({ label: `${label}.mode` });
  const messages = data<readonly Tinkerer.Message[]>({ label: `${label}.messages`, initial: [] });
  const status = data<Tinkerer.Status>({ label: `${label}.status`, initial: "idle" });
  const text = data<string>({ label: `${label}.text`, initial: "" });
  const usage = data<Tinkerer.Usage>({
    label: `${label}.usage`,
    initial: { input: 0, cached: 0, output: 0 },
  });
  const settings = data<Tinkerer.Settings | undefined>({
    label: `${label}.settings`,
    initial: undefined,
  });
  const inbox = data<readonly Tinkerer.Entry[]>({ label: `${label}.inbox`, initial: noEntries });
  const step: Tinkerer.Frame["step"] = operation({
    label: `${label}.http.step`,
    depends: { send },
    run: async ({ send: sendIt }, ctx: Operation.Ctx<Tinkerer.StepInput>) => {
      const res = await sendIt.run({
        input: HttpRequest.post(ctx.input.url, {
          headers: ctx.input.headers,
          body: HttpRequest.bodyJson(ctx.input.body),
        }),
      });
      return res.sse();
    },
  });
  const toolDeps = readToolDeps(rows);
  const gateDeps: { gate?: Tinkerer.Gate } = config.gate === undefined ? {} : { gate: config.gate };
  const turn = operation({
    label: `${label}.turn`,
    input: readPrompt(label),
    depends: {
      configs: configTag.all,
      mode: mode.optional,
      step,
      messages: messages.controller,
      status: status.controller,
      text: text.controller,
      usage: usage.controller,
      settings: settings.controller,
      inbox: inbox.controller,
      ...toolDeps,
      ...gateDeps,
    },
    run: async (deps, ctx) => {
      const prompt = ctx.input;
      const merged = mergeConfigs(deps.configs);
      const seen = readRequired(merged, label);
      seedSystem(deps.messages, seen.system);
      seedSettings(deps.settings, deps.mode, seen);
      try {
        openTurn(deps, prompt);
        return await runLoop(deps, ctx, { label, seen, merged, rows });
      } catch (error) {
        if (!ctx.signal.aborted) deps.status.set("failed");
        throw error;
      }
    },
  });
  return {
    label,
    config: configTag,
    messages,
    status,
    text,
    usage,
    step,
    turn,
    mode,
    settings,
    inbox,
    tools: rows,
  };
}

export function family<T>(config: {
  label: string;
  initial: T;
  parse?: Data.Parse<T>;
  eq?: (a: T, b: T) => boolean;
}): Sync.Family<T> {
  const cell = data({
    label: config.label,
    initial: config.initial,
    parse: config.parse,
    eq: config.eq,
  });
  const found = new Map<string, Namespace>();
  const arrivals = new Set<(id: string) => void>();
  function member(id: string): Namespace {
    const hit = found.get(id);
    if (hit !== undefined) return hit;
    const ns = namespace();
    found.set(id, ns);
    for (const arrival of arrivals) arrival(id);
    return ns;
  }
  function members(): string[] {
    return [...found.keys()];
  }
  function onMember(listener: (id: string) => void): () => void {
    arrivals.add(listener);
    function unlisten(): void {
      arrivals.delete(listener);
    }
    return unlisten;
  }
  return Object.assign(member, { cell, label: config.label, members, onMember });
}

export function tool(
  op: Operation.Handle<unknown, unknown>,
  meta: Tinkerer.Tool["meta"],
): Tinkerer.Tool {
  return { op, meta };
}

function answerRoute<T, I>(op: Operation.Handle<T, I>, route: HonoScope.Route<I, T>): Endpoint {
  const run = (c: Context): Promise<Response> => {
    const session = (c as Context<SessionEnv>).get("tinker.session");
    if (!session) raise("NoSession", { label: op.label });
    const onError = (c as Context<SessionEnv>).get("tinker.onError");
    return session.run({
      label: `${c.req.method} ${c.req.routePath}`,
      depends: { op },
      run: readRoute(route, c, onError, op.label),
    });
  };
  return run;
}

function readRoute<T, I>(
  route: HonoScope.Route<I, T>,
  c: Context,
  onError: HonoScope.OnError | undefined,
  label: string,
): (
  deps: { readonly op: Scope.OperationController<T, I> },
  ctx: Operation.Ctx<void>,
) => Promise<Response> {
  return ({ op: flow }, ctx) => {
    const method = c.req.method;
    const pattern = c.req.routePath;
    const path = c.req.path;
    const span = ctx.obs.span;
    if (span) {
      span.attributes.method = method;
      span.attributes.route = pattern;
      span.attributes.path = path;
    }
    const done = (response: Response): Response => {
      if (span) span.attributes.status = response.status;
      ctx.log("http request", {
        method,
        route: pattern,
        path,
        status: response.status,
      });
      return response;
    };
    const respond: HonoScope.Respond<T> = route.respond ?? defaultRespond;
    const readInput = route.input;
    const answer = async (): Promise<Response> => {
      let value: Awaited<T>;
      try {
        const raw = readInput !== undefined ? readInput(c) : undefined;
        const ran =
          readInput !== undefined
            ? isThenable(raw)
              ? flow.run({ rawInput: await readBody(raw, label) })
              : flow.run({ rawInput: raw })
            : runVoid(flow);
        value = await ran;
      } catch (error: unknown) {
        const mapped = await mapError(error, c, onError, ctx.signal);
        if (mapped === undefined) {
          done(new Response(null, { status: 499 }));
          throw error;
        }
        return done(mapped);
      }
      return done(await respond(value, c));
    };
    return answer();
  };
}

function readCall(
  scope: Scope.Handle,
  name: string,
  op: Operation.Handle<unknown, unknown>,
  meta: Mcp.Tool,
): (args: Record<string, unknown>) => Promise<CallToolResult> {
  return (args) =>
    scope
      .session((s) =>
        s.run(
          {
            label: `mcp ${name}`,
            depends: { op },
            run: async ({ op: flow }, ctx) => {
              try {
                const value = await flow.run({ rawInput: args });
                ctx.log("mcp tool", {
                  tool: name,
                  ok: true,
                });
                return answerTool(meta, value);
              } catch (error: unknown) {
                ctx.log("mcp tool", {
                  tool: name,
                  ok: false,
                });
                throw error;
              }
            },
          },
          { input: args },
        ),
      )
      .catch((error: unknown) => {
        if (isCoreError(error, "DataValidationFailed")) return failureResult("invalid input");
        return failureResult(String(error));
      });
}

