function lazyCheckRoute(): Process.Route {
  let cached: Promise<typeof check> | undefined;
  const once = (): Promise<typeof check> => {
    cached ??= Promise.resolve(loadCheck()).catch((error: unknown) => {
      cached = undefined;
      throw error;
    });
    return cached;
  };
  return {
    name: "lazy-check",
    description: "check a file, loaded lazily",
    entry: async () => {
      const flow = await once();
      return {
        op: operation({
          label: "lazy-check",
          depends: { argv: argv.required, io: io.required, check: flow },
          run: ({ argv: args, io: out, check: op }) => {
            const value = op.run({ rawInput: args[0] });
            out.write(jsonLine(value) ?? "");
            return 0;
          },
        }),
      };
    },
  };
}

function lazyPingRoute(loads: { count: number }): Process.Route {
  let cached: Promise<typeof ping> | undefined;
  const once = (): Promise<typeof ping> => {
    cached ??= Promise.resolve(loadPing())
      .then((flow) => {
        loads.count += 1;
        return flow;
      })
      .catch((error: unknown) => {
        cached = undefined;
        throw error;
      });
    return cached;
  };
  return {
    name: "ping",
    entry: async () => ({
      op: operation({
        label: "ping",
        depends: { io: io.required, ping: await once() },
        run: ({ io: out, ping: flow }) => {
          out.write(`${JSON.stringify(flow.run())}\n`);
          return 0;
        },
      }),
    }),
  };
}

export function publishAfterCommit(): Scope.Extension<void> {
  let runPublish: (() => Promise<unknown>) | undefined;
  return extension({
    label: "tracker.publishAfterCommit",
    start: (scope, _ctx, next) => {
      runPublish = () =>
        scope.run({
          label: "publish after commit",
          depends: { publish: publishIssues },
          run: async ({ publish }, ctx) => {
            try {
              await publish.run();
            } catch (error) {
              ctx.log.error("publish failed", describeError(error));
            }
          },
        });
      return next();
    },
    session: async (handle, next) => {
      const found = handle.resolve(request.optional);
      const method = found.present ? found.value.method : undefined;
      const ended = await next();
      if (ended.status === "success" && method !== undefined && method !== "GET")
        await runPublish?.();
      return ended;
    },
  });
}

function readServer(
  sdk: ClaudeCode.Sdk,
  label: string,
  tools: readonly Harness.ToolCall<ClaudeCode.Calls>[],
): McpServerConfig {
  return sdk.createSdkMcpServer({
    name: label,
    tools: tools.map(({ op, meta, run }) =>
      sdk.tool(meta.name ?? op.label, meta.description, meta.schema, async (args) =>
        answerTool(meta, await run.run({ rawInput: args })),
      ),
    ),
  });
}

